function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs a root.';
  // In level order, the item at index i is a child of the floor((i - 1) / 2)-th node seen so far.
  let nodes = 0;
  for (let i = 0; i < root.length; i++) {
    if (i > 0 && Math.floor((i - 1) / 2) >= nodes) return 'Every value after the root needs a parent node before it.';
    if (root[i] !== null) nodes++;
  }
  const values = root.filter(v => v !== null);
  if (values.length < 2 || values.length > 10000) return 'The tree has 2 to 10^4 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > values.length)) return 'Node values are integers from 1 to n.';
  if (new Set(values).size !== values.length) return 'Node values must be unique.';
  return null;
}

