function adapt(input, solve, kit) {
  const root = kit.toTree(input[0]);
  // Find the leaves with an explicit stack before any links are added.
  const leaves = [];
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    if (!node.left && !node.right) leaves.push(node);
    if (node.right) stack.push(node.right);
    if (node.left) stack.push(node.left);
  }
  leaves.sort((a, b) => a.val - b.val);
  const k = leaves.length;
  leaves.forEach((leaf, i) => {
    leaf.right = leaves[(i + 1) % k];
    leaf.left = leaves[(i - 1 + k) % k];
  });
  const result = solve(root);
  if (!Number.isInteger(result)) throw new Error('Return the height as an integer.');
  return result;
}

