function heightOfTree(root) {
  const isLeaf = root.left !== null && root.left.right === root;
  if (isLeaf) {
    return 0;
  }
  let height = 0;
  if (root.left !== null) {
    height = Math.max(height, 1 + heightOfTree(root.left));
  }
  if (root.right !== null) {
    height = Math.max(height, 1 + heightOfTree(root.right));
  }
  return height;
}

