function heightOfTree(root) {
  // Level by level; a leaf is the node its right neighbour points back to.
  let level = [root];
  let depth = -1;
  while (level.length) {
    depth++;
    const next = [];
    for (const node of level) {
      if (node.right && node.right.left === node) continue;
      if (node.left) next.push(node.left);
      if (node.right) next.push(node.right);
    }
    level = next;
  }
  return depth;
}

