function generate(rand, size) {
  const n = size === 'large' ? 600 + Math.floor(rand() * 301) : 2 + Math.floor(rand() * 9);
  const values = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  // A deep tree attaches each node near the most recent ones; a bushy tree attaches anywhere.
  const deep = rand() < 0.4;
  const nodes = [{ val: values[0], left: null, right: null }];
  for (let i = 1; i < n; i++) {
    let parent;
    do {
      const pick = deep ? nodes.length - 1 - Math.floor(rand() * Math.min(3, nodes.length)) : Math.floor(rand() * nodes.length);
      parent = nodes[pick];
    } while (parent.left && parent.right);
    const child = { val: values[i], left: null, right: null };
    if (!parent.left && (parent.right || rand() < 0.5)) parent.left = child;
    else parent.right = child;
    nodes.push(child);
  }
  const out = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    if (!node) { out.push(null); continue; }
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
